#nullable enable
class C
{
    bool M0(object obj) => false;

    void M1(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is true or false
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is not (true or false)
            ? x.ToString() // 2
            : y.ToString();
    }
}

